import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.wVcpyw2-.js";const p=JSON.parse('{"title":"短信验证码","description":"短信验证码：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/sms.md","filePath":"features/sms.md","lastUpdated":1785051348000}'),l={name:"features/sms.md"};function d(s,t,i,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="短信验证码" tabindex="-1">短信验证码 <a class="header-anchor" href="#短信验证码" aria-label="Permalink to &quot;短信验证码&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>通过腾讯云短信向用户手机发送注册、登录等场景的验证码。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已在 <a href="https://console.cloud.tencent.com/smsv2" target="_blank" rel="noreferrer">腾讯云短信控制台</a> 创建应用、签名与 <strong>验证码类</strong> 模板，且审核通过。</li><li>站点服务器可访问腾讯云 API。</li><li>您的账号具备 <strong>系统配置</strong> 读写权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>系统设置 → 系统配置 → 腾讯云短信</strong> Tab</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>SdkAppId</td><td>短信控制台 → 应用管理</td></tr><tr><td>签名</td><td>已审核通过的短信签名</td></tr><tr><td>模板 ID</td><td>验证码模板（变量通常为 <code>{1}</code> 验证码、<code>{2}</code> 有效期分钟数）</td></tr><tr><td>SecretId / SecretKey</td><td>腾讯云 API 密钥（建议使用子账号并仅授予短信权限）</td></tr></tbody></table><p>填写后保存。若页面提供「发送测试」按钮，可向管理员手机号发一条验证。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>短信是否 <strong>强制</strong> 出现在注册 / 登录流程，由 <strong>区域管理 → 用户配置</strong> 控制：</p><table tabindex="0"><thead><tr><th>开关</th><th>含义</th></tr></thead><tbody><tr><td>注册强制验证码</td><td>新用户注册必须通过手机验证码</td></tr><tr><td>登录强制验证码</td><td>密码登录时必须输入短信验证码</td></tr></tbody></table><p>即使全站短信参数已填，若区域未开启上述开关，对应环节不会发送短信。</p><p>另外可在 <strong>用户配置</strong> 中设置验证码长度、有效期等平台/区域级规则（以页面实际字段为准）。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>用户配置</strong> 中为目标区域开启「注册强制验证码」或「登录强制验证码」。</li><li>在客户端发起注册或登录，应收到短信且能完成验证。</li><li><strong>通知控制台 → 通知记录</strong> 中可看到短信类投递记录（如已启用通知模块）。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>保存成功但收不到短信</strong></p><ul><li>检查签名、模板 ID 是否与腾讯云控制台一致，模板类型须为验证码。</li><li>确认 SecretId / SecretKey 有效，子账号权限包含 SMS。</li><li>查看手机是否被运营商拦截；同一号码短时间发送过多会触发限流。</li></ul><p><strong>仅部分区域需要验证码</strong></p><ul><li>在 <strong>用户配置</strong> 中分别编辑各区域，勿只改平台默认行。</li></ul><p><strong>与微信登录的关系</strong></p><ul><li>微信登录与短信验证码独立；用户走微信一键登录时通常不需要短信，除非业务另行要求绑定手机。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/user-rules">用户规则</a></li><li><a href="/config/system-settings">系统配置总览</a></li></ul>',25)])])}const g=a(l,[["render",d]]);export{p as __pageData,g as default};
